    db = new SQL.Database();
  }

  db.exec("PRAGMA foreign_keys = ON");

  db.exec(`
    CREATE TABLE IF NOT EXISTS usuarios (
      id TEXT PRIMARY KEY,
      nome TEXT NOT NULL,
      papel TEXT NOT NULL CHECK (papel IN ('organizacao', 'participante'))
    );

    CREATE TABLE IF NOT EXISTS salas (
      id TEXT PRIMARY KEY,
      nome TEXT NOT NULL,
      capacidade INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS atividades (
      id TEXT PRIMARY KEY,
      titulo TEXT NOT NULL,
      tipo TEXT NOT NULL CHECK (tipo IN ('palestra', 'minicurso')),
      sala_id TEXT NOT NULL REFERENCES salas(id),
      vagas INTEGER NOT NULL,
      situacao TEXT NOT NULL DEFAULT 'prevista' CHECK (situacao IN ('prevista', 'em_andamento', 'encerrada', 'cancelada')),
      criada_em TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS encontros (
      id TEXT PRIMARY KEY,
      atividade_id TEXT NOT NULL REFERENCES atividades(id) ON DELETE CASCADE,
      inicio TEXT NOT NULL,
      fim TEXT NOT NULL,
      ordem INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS inscricoes (
      id TEXT PRIMARY KEY,
      atividade_id TEXT NOT NULL REFERENCES atividades(id) ON DELETE CASCADE,
      participante_id TEXT NOT NULL REFERENCES usuarios(id),
      status TEXT NOT NULL CHECK (status IN ('confirmada', 'em_espera', 'convocada', 'cancelada', 'expirada')),
      posicao_na_espera INTEGER,
      convocada_ate TEXT,
      criada_em TEXT NOT NULL DEFAULT (datetime('now')),
      UNIQUE (atividade_id, participante_id)
    );

    CREATE TABLE IF NOT EXISTS presencas (
      id TEXT PRIMARY KEY,
      encontro_id TEXT NOT NULL REFERENCES encontros(id) ON DELETE CASCADE,
      participante_id TEXT NOT NULL REFERENCES usuarios(id),
      origem TEXT NOT NULL CHECK (origem IN ('qr', 'qr_offline', 'manual')),
      lido_em TEXT NOT NULL,
      registrada_em TEXT NOT NULL DEFAULT (datetime('now')),
      justificativa TEXT
    );

    CREATE TABLE IF NOT EXISTS certificados (
      codigo TEXT PRIMARY KEY,
      atividade_id TEXT NOT NULL REFERENCES atividades(id),
      participante_id TEXT NOT NULL REFERENCES usuarios(id),
      carga_horaria_minutos INTEGER NOT NULL,
      presencas INTEGER NOT NULL,
      encontros INTEGER NOT NULL,
      emitido_em TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS bloqueios (
      participante_id TEXT PRIMARY KEY REFERENCES usuarios(id),
      atividades TEXT NOT NULL,
      bloqueado_desde TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS relogio_teste (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      agora TEXT NOT NULL
    );
  `);

  dbInstance = db;
  return db;
}

export function salvarBanco(db: Database) {
  ensureDbDir();
  const data = db.export();
  fs.writeFileSync(DB_PATH, Buffer.from(data));
}

export function carregarDadosIniciais(db: Database) {
  const usuarios = [
    { id: "org-ana", nome: "Ana Beatriz Lima", papel: "organizacao" },
    { id: "org-bruno", nome: "Bruno Tavares", papel: "organizacao" },
    { id: "p-carla", nome: "Carla Mendes Souza", papel: "participante" },
    { id: "p-diego", nome: "Diego Alves", papel: "participante" },
    { id: "p-elisa", nome: "Elisa Fernandes da Rocha", papel: "participante" },
    { id: "p-fabio", nome: "Fábio Nogueira", papel: "participante" },
    { id: "p-gabriela", nome: "Gabriela Moura Castro", papel: "participante" },
    { id: "p-heitor", nome: "Heitor Campos", papel: "participante" },
    { id: "p-isadora", nome: "Isadora Ribeiro dos Santos", papel: "participante" },
    { id: "p-joao", nome: "João Pedro Martins", papel: "participante" },
  ];

  const salas = [
    { id: "auditorio", nome: "Auditório Central", capacidade: 200 },
    { id: "sala-101", nome: "Sala 101", capacidade: 40 },
    { id: "sala-102", nome: "Sala 102", capacidade: 40 },
    { id: "lab-3", nome: "Laboratório 3", capacidade: 20 },
  ];

  const insertUsuario = db.prepare(
    "INSERT OR REPLACE INTO usuarios (id, nome, papel) VALUES (?, ?, ?)"
  );
  const insertSala = db.prepare(
    "INSERT OR REPLACE INTO salas (id, nome, capacidade) VALUES (?, ?, ?)"
  );

  for (const u of usuarios) insertUsuario.run([u.id, u.nome, u.papel]);
  for (const s of salas) insertSala.run([s.id, s.nome, s.capacidade]);
}

export function resetarBanco(db: Database) {
  const tabelas = [
    "presencas",
    "certificados",
    "inscricoes",
    "encontros",
    "atividades",
    "bloqueios",
  ];

  for (const t of tabelas) {
    db.run(`DELETE FROM ${t}`);
  }

  carregarDadosIniciais(db);
}

export function obterRelogioTeste(db: Database): string {
  const stmt = db.prepare("SELECT agora FROM relogio_teste WHERE id = 1");
  const result = stmt.getAsObject();
  if (result && result.agora) return result.agora as string;

  const inicial = "2026-10-13T09:00:00-03:00";
  db.run("INSERT INTO relogio_teste (id, agora) VALUES (1, ?)", [inicial]);
  return inicial;
}

export function definirRelogioTeste(db: Database, agora: string): string {
  db.run("INSERT OR REPLACE INTO relogio_teste (id, agora) VALUES (1, ?)", [agora]);
  return agora;
}

export type SqlJsDatabase = Database;

import "fastify";
import { Database } from "sql.js";

declare module "fastify" {
  interface FastifyInstance {
    db: Database;
  }

  interface FastifyRequest {
    usuario?: { id: string; papel: string };
  }
}

import { FastifyRequest, FastifyReply } from "fastify";

const ROTAS_PUBLICAS = [
  "/certificados/:codigo",
  "/_teste/reset",
  "/_teste/relogio",
];

function isRotaPublica(path: string): boolean {
  return ROTAS_PUBLICAS.some((r) => {
    const regex = new RegExp("^" + r.replace(":codigo", "[^/]+") + "$");
    return regex.test(path);
  });
}

export async function verifyAuth(req: FastifyRequest, reply: FastifyReply) {
  if (isRotaPublica(req.routeOptions?.url || req.url)) {
    return;
  }

  const usuarioId = req.headers["x-usuario"] as string | undefined;
  if (!usuarioId) {
    return reply.code(401).send({
      erro: "USUARIO_DESCONHECIDO",
      mensagem: "Cabeçalho X-Usuario é obrigatório",
    });
  }

  const db = req.server.db;
  const stmt = db.prepare("SELECT id, papel FROM usuarios WHERE id = ?");
  const result = stmt.getAsObject([usuarioId]) as { id: string; papel: string } | undefined;

  if (!result) {
    return reply.code(401).send({
      erro: "USUARIO_DESCONHECIDO",
      mensagem: "Usuário não encontrado",
    });
  }

  req.usuario = { id: result.id, papel: result.papel };
}

import { FastifyInstance } from "fastify";
import { z } from "zod";
import { verifyAuth } from "../middleware/auth.js";

const SalaSchema = z.object({
  id: z.string(),
  nome: z.string(),
  capacidade: z.number().int(),
});

export function registrarRotasSalas(app: FastifyInstance) {
  app.get(
    "/salas",
    { preHandler: verifyAuth, schema: { response: { 200: z.array(SalaSchema) } } },
    async (_req, reply) => {
      const db = app.db;
      const stmt = db.prepare("SELECT id, nome, capacidade FROM salas ORDER BY id");
      const salas = stmt.all() as Array<{ id: string; nome: string; capacidade: number }>;
      return reply.send(salas);
    }
  );
}

import { FastifyInstance } from "fastify";
import { resetarBanco, obterRelogioTeste, definirRelogioTeste, salvarBanco } from "../db.js";

export function registrarRotasTeste(app: FastifyInstance) {
  app.post("/_teste/reset", async (_req, reply) => {
    const db = app.db;
    resetarBanco(db);
    definirRelogioTeste(db, "2026-10-13T09:00:00-03:00");
    salvarBanco(db);
    return reply.code(204).send();
  });

  app.get("/_teste/relogio", async (_req, reply) => {
    const db = app.db;
    const agora = obterRelogioTeste(db);
    return reply.send({ agora });
  });

  app.put("/_teste/relogio", async (req, reply) => {
    const { agora } = req.body as { agora: string };
    if (!agora) {
      return reply.code(422).send({
        erro: "DADOS_INVALIDOS",
        mensagem: "Campo 'agora' é obrigatório",
      });
    }
    const db = app.db;
    const novoAgora = definirRelogioTeste(db, agora);
    salvarBanco(db);
    return reply.send({ agora: novoAgora });
  });
}

