  "/_teste/relogio",
];

function isRotaPublica(path: string): boolean {
  return ROTAS_PUBLICAS.some((r) => {
    const regex = new RegExp("^" + r.replace(":codigo", "[^/]+") + "$");
    return regex.test(path);
  });
}

function rowToUsuario(row: Record<string, unknown>) {
  return {
    id: row.id as string,
    papel: row.papel as string,
  };
}

export async function verifyAuth(req: FastifyRequest, reply: FastifyReply) {
  if (isRotaPublica(req.routeOptions?.url || req.url)) {
    return;
  }

  const usuarioId = req.headers["x-usuario"] as string | undefined;
  if (!usuarioId) {
    return reply.code(401).send({
      erro: "USUARIO_DESCONHECIDO",
      mensagem: "Cabeçalho X-Usuario é obrigatório",
    });
  }

  const db = req.server.db;
  const result = db.exec("SELECT id, papel FROM usuarios WHERE id = ?", [usuarioId]);
  if (result.length === 0 || result[0].values.length === 0) {
    return reply.code(401).send({
      erro: "USUARIO_DESCONHECIDO",
      mensagem: "Usuário não encontrado",
    });
  }
  const cols = result[0].columns;
  const vals = result[0].values[0];
  const row: Record<string, unknown> = {};
  cols.forEach((c, i) => { row[c] = vals[i]; });
  const usuario = rowToUsuario(row);

  req.usuario = { id: usuario.id, papel: usuario.papel };
}

import { FastifyInstance } from "fastify";
import { resetarBanco, obterRelogioTeste, definirRelogioTeste, salvarBanco } from "../db.js";

export function registrarRotasTeste(app: FastifyInstance) {
  app.post("/_teste/reset", async (_req, reply) => {
    const db = app.db;
    resetarBanco(db);
    definirRelogioTeste(db, "2026-10-13T09:00:00-03:00");
    salvarBanco(db);
    return reply.code(204).send();
  });

  app.get("/_teste/relogio", async (_req, reply) => {
    const db = app.db;
    const agora = obterRelogioTeste(db);
    return reply.send({ agora });
  });

  app.put("/_teste/relogio", async (req, reply) => {
    const { agora } = req.body as { agora: string };
    if (!agora) {
      return reply.code(422).send({
        erro: "DADOS_INVALIDOS",
        mensagem: "Campo 'agora' é obrigatório",
      });
    }
    const db = app.db;
    const novoAgora = definirRelogioTeste(db, agora);
    salvarBanco(db);
    return reply.send({ agora: novoAgora });
  });
}

import Fastify from "fastify";
import { inicializarBanco } from "./db.js";
import { registrarRotasTeste } from "./rotas/teste.js";
import { registrarRotasSalas } from "./rotas/salas.js";
import { registrarRotasAtividades } from "./rotas/atividades.js";

let cachedDb: Awaited<ReturnType<typeof inicializarBanco>> | null = null;

async function getDb() {
  if (!cachedDb) {
    cachedDb = await inicializarBanco();
  }
  return cachedDb;
}

export async function createServer() {
  const app = Fastify({ logger: false });

  const db = await getDb();

  app.decorate("db", db);

  // Permitir body vazio em POST
  app.addContentTypeParser("application/json", { parseAs: "string" }, (req, body, done) => {
    try {
      const json = body ? JSON.parse(body as string) : {};
      done(null, json);
    } catch (err) {
      done(err as Error, undefined);
    }
  });

  if (process.env.MODO_TESTE === "1") {
    registrarRotasTeste(app);
  }

  registrarRotasSalas(app);
  registrarRotasAtividades(app);

  return app;
}

